L(OA26, 5,
  MAT26,
  "Aprenderé a construir una síntesis completa de un texto y a comprobar que es fiel, breve, ordenada y con las ideas principales.",
  ["Distingo ideas principales y secundarias.", "Parafraseo e integro fuentes."],
  ["Una síntesis es un texto breve que reúne las ideas principales de uno o más textos, escrito con tus palabras y en un orden lógico. Es más corta que el original y no incluye opiniones personales. Sirve para estudiar, preparar una investigación o recordar lo esencial.",
   "Pasos para construirla: 1) lee y subraya ideas principales; 2) escribe un esquema o palabras clave; 3) redacta las ideas con tus palabras y en el mismo orden lógico del texto; 4) une las ideas con conectores; 5) comprueba. Una buena síntesis suele tener entre un cuarto y un tercio de la extensión original. Si el original tiene 120 palabras, una síntesis de 30 a 40 es razonable.",
   "Para comprobar tu síntesis, usa una lista: ¿incluye la idea principal?, ¿incluye las secundarias necesarias?, ¿es fiel (no cambia ni agrega datos)?, ¿está escrita con mis palabras?, ¿es breve?, ¿tiene orden lógico?, ¿no incluye mi opinión? Si falla un punto, corrígelo. Luego relee la síntesis sin mirar el texto: ¿se entiende por sí sola?"],
  [("síntesis", "texto breve que reúne las ideas principales de un texto o varios"), ("fiel", "que respeta el sentido y los datos del original"), ("orden lógico", "secuencia de ideas que se entiende"), ("comprobar", "verificar con una lista de criterios")],
  [("Calcular la extensión", "Un texto tiene 120 palabras. Una síntesis equivale a un cuarto. ¿Cuántas palabras tendría?",
    ["Un cuarto significa dividir entre 4.", "120 ÷ 4.", "Son 30 palabras."],
    "30 palabras"),
   ("Comprobar fidelidad", "Original: «Las abejas se comunican con danzas». Síntesis: «Las abejas hablan con sonidos». ¿Es fiel?",
    ["Comparo con el original.", "Cambia «danzas» por «sonidos».", "No es fiel."],
    "No es fiel: cambia el medio de comunicación")],
  [("Incluir la opinión personal.", "Se mezcla lo que uno piensa.", "La síntesis solo reúne lo que dice el texto."),
   ("Hacer una síntesis tan larga como el original.", "No se prioriza.", "Selecciona solo las ideas principales.")],
  ([E("¿Una síntesis incluye opiniones personales?", "No", "Solo reúne lo que dice el texto."),
    E("¿Una síntesis es más corta que el original?", "Sí", "Reúne lo esencial."),
    E("¿Una síntesis se escribe con tus palabras?", "Sí", "Es una paráfrasis de lo esencial.")],
   [E("Original: «Las abejas se comunican con danzas». ¿Cuál síntesis es fiel: «Las abejas se comunican con danzas» o «Las abejas se comunican con sonidos»?", "Las abejas se comunican con danzas", "Conserva el dato."),
    E("¿Qué se comprueba primero en una síntesis: que incluya la idea principal o que esté en cursiva?", "Que incluya la idea principal", "Es lo central."),
    E("¿El orden de la síntesis debe ser lógico?", "Sí", "Para que se entienda.")],
   [arith("Un texto tiene 160 palabras. Una síntesis equivale a un cuarto de su extensión. ¿Cuántas palabras tiene?", "160//4", "Un cuarto se calcula dividiendo entre 4.", " palabras"),
    arith("Otro texto tiene 90 palabras. Una síntesis equivale a un tercio. ¿Cuántas palabras tiene?", "90//3", "Un tercio se calcula dividiendo entre 3.", " palabras"),
    E("Texto de ejemplo: «El mural del barrio muestra la historia de la comuna. Lo pintaron vecinos durante un verano». Síntesis: «Vecinos pintaron un mural sobre la historia de la comuna». ¿Es fiel?", "Sí", "Incluye la idea central sin agregar datos.")],
   [E("Una síntesis dice: «Me parece que el mural es feo». ¿Qué problema tiene?", "Incluye una opinión personal", "Una síntesis no opina."),
    E("Una síntesis de 100 palabras para un texto de 120. ¿Qué problema tiene?", "Es casi tan larga como el original", "No prioriza ideas.")],
   [E("Evalúa esta síntesis de ejemplo: «Las fábulas usan animales para enseñar una lección llamada moraleja». ¿Incluye la idea principal?", "Sí", "Dice que usan animales para enseñar una lección."),
    E("Un compañero hace una síntesis que cambia dos cifras del original. ¿Qué criterio falla?", "La fidelidad", "No conserva los datos.")]),
  [E("Un estudiante hace la síntesis de un capítulo de 600 palabras y obtiene 450 palabras. ¿Es breve?", "No", "Es casi tan larga como el original.")],
  [E("¿Una síntesis es más breve que el original?", "Sí", "Reúne solo lo esencial."),
   E("¿Se comprueba la síntesis con una lista de criterios?", "Sí", "Ayuda a corregirla."),
   E("¿Una síntesis debe entenderse por sí sola?", "Sí", "Quien la lea no debería necesitar el original.")],
  ("Lee este texto de ejemplo (50 palabras): «Los murales urbanos son pinturas realizadas en muros de espacios públicos. Surgen por iniciativa de artistas, vecinos o escuelas. Pueden contar la historia de un barrio, denunciar problemas o celebrar la cultura local. Además, mejoran el aspecto de los lugares y fomentan que las personas participen y cuiden su entorno». Escribe una síntesis de 12 a 17 palabras (entre un cuarto y un tercio del texto), con tus palabras, y comprueba con la lista de siete criterios.",
   "Ejemplo: «Los murales urbanos son pinturas en muros públicos que cuentan historias y mejoran el entorno» (15 palabras). Criterios: incluye la idea principal, es fiel, está en mis palabras, es breve, tiene orden lógico y no opina.",
   ["incluye la idea principal", "es fiel y breve", "no incluye opinión"], ["síntesis", "lista de comprobación"], ["copiar frases", "incluir opiniones"], "Lee tu síntesis a otra persona y pregúntale si entendió el texto sin leer el original."),
  "Haz la síntesis de un artículo corto de una revista o diario de tu casa.",
  "Escribe una síntesis de un mismo texto con 20, 30 y 40 palabras y compara cuál sirve mejor para estudiar.")
